use std::cell::RefCell;
use std::rc::{Rc, Weak};

struct Node {
    value: i32,
    parent: RefCell<Weak<Node>>,       // child -> parent: weak, doesn't keep the parent alive
    children: RefCell<Vec<Rc<Node>>>,  // parent -> child: strong, keeps children alive
}

let leaf = Rc::new(Node {
    value: 3,
    parent: RefCell::new(Weak::new()),
    children: RefCell::new(vec![]),
});

let branch = Rc::new(Node {
    value: 5,
    parent: RefCell::new(Weak::new()),
    children: RefCell::new(vec![Rc::clone(&leaf)]),
});

*leaf.parent.borrow_mut() = Rc::downgrade(&branch);

match leaf.parent.borrow().upgrade() {
    Some(p) => println!("leaf's parent is alive, value {}", p.value),
    None => println!("leaf's parent is gone"),
}

