use std::sync::mpsc;
use std::thread;

let (tx, rx) = mpsc::channel();

for id in 0..3 {
    let tx = tx.clone(); // each thread gets its own cloned sender
    thread::spawn(move || {
        tx.send(id).unwrap();
    });
}
drop(tx); // drop the original so the loop below can end

for received in rx { // Receiver is an Iterator
    println!("got {received}");
}
